using System.Text.RegularExpressions;

namespace GTAModManager.Core.Mods;

/// <summary>Display names: mod files and folders stay as they are; only the UI label changes.</summary>
public static partial class ModNames
{
    /// <summary>Display adapter for legacy operation titles generated by ModHub.</summary>
    public static string DisplayOperationTitle(string name)
    {
        // History written before the "GMM" prefix was dropped from component names.
        name = name switch
        {
            "Установка GMM PED Selector" => "Установка Ped Selector",
            "Установка GMM AddonPeds" => "Установка AddonPeds",
            _ => name,
        };
        if (name == Inventory.InstalledModList.EngineSoundsName)
            return Localization.L.T("core.dlc.engineSoundsGroup");
        return
            name.StartsWith("База для моддинга:", StringComparison.Ordinal)
            || name.StartsWith("Дополнительно:", StringComparison.Ordinal)
            || name.StartsWith("Правки архивов игры:", StringComparison.Ordinal)
            || name
                is Inventory.InstalledModList.BaseName
                    or "Компоненты GameConfig"
                    or "Установка Ped Selector"
                    or "Установка AddonPeds"
            ? Localization.L.Owned(name)
            : Pretty(name);
    }

    static readonly Lazy<string[]> HotkeyPrefixes = new(() =>
        Localization
            .LocalizationService.Current.AllValues("core.keybinds.hotkey")
            .Select(v => v.IndexOf("{0}", StringComparison.Ordinal) is var i and > 0 ? v[..i] : v)
            .Append("Горячая клавиша: ")
            .Distinct(StringComparer.Ordinal)
            .ToArray()
    );

    /// <summary>
    /// A hotkey change made on the Hotkeys page (stored in whatever language was active). It edits a mod's settings
    /// file but is not a mod of its own: My Mods and the Hotkeys mod list keep the file with the mod that installed it.
    /// </summary>
    public static bool IsHotkeyEdit(string? title) =>
        title is { Length: > 0 } && HotkeyPrefixes.Value.Any(p => title.StartsWith(p, StringComparison.Ordinal));

    // GTA5-Mods prefixes uploaded file names with 6 hex characters and a hyphen ("a9db86-Lara_V_1.5a").
    // At least one digit is required: a word made of the letters a–f ("deface-…") is part of the real name.
    [GeneratedRegex(@"^(?=[0-9a-f]{0,5}[0-9])[0-9a-f]{6}-(?=.)", RegexOptions.IgnoreCase)]
    private static partial Regex UploadPrefix();

    [GeneratedRegex(@"\s{2,}")]
    private static partial Regex Spaces();

    /// <summary>«a9db86-Lara_V_1.5a» → «Lara V 1.5a».</summary>
    public static string Pretty(string? name)
    {
        if (string.IsNullOrWhiteSpace(name))
            return name ?? "";
        var s = UploadPrefix().Replace(name.Trim(), "");
        s = Spaces().Replace(s.Replace('_', ' '), " ").Trim();
        return s.Length == 0 ? name.Trim() : s;
    }
}
